import{_ as t,o as d,c as o,a2 as a}from"./chunks/framework.KobcctIO.js";const p=JSON.parse('{"title":"Référence des Canaux IPC","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/dev/ipc-reference.md","filePath":"fr/guide/dev/ipc-reference.md"}'),c={name:"fr/guide/dev/ipc-reference.md"};function r(i,e,n,s,u,l){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="reference-des-canaux-ipc" tabindex="-1">Référence des Canaux IPC <a class="header-anchor" href="#reference-des-canaux-ipc" aria-label="Permalink to &quot;Référence des Canaux IPC&quot;">​</a></h1><div style="display:flex;gap:8px;margin:1rem 0;flex-wrap:wrap;"><img src="https://img.shields.io/badge/Protocole-IPC%20Asynchrone-blue.svg" alt="Protocole"><img src="https://img.shields.io/badge/Contr%C3%B4le-Whitelist%20Statique-green.svg" alt="Contrôle"><img src="https://img.shields.io/badge/Preload-contextBridge-orange.svg" alt="Preload"></div><p>Toutes les communications entre le Renderer Process (DOM) et le Main Process (Node.js) transitent par une <strong>liste blanche statique</strong> de canaux IPC validée dans <code>preload.js</code>. Tout appel ciblant un canal non répertorié est rejeté avec une exception de sécurité.</p><hr><h2 id="_1-canaux-d-authentification-src-main-ipc-auth-js" tabindex="-1">1. Canaux d&#39;Authentification (<code>src/main/ipc-auth.js</code>) <a class="header-anchor" href="#_1-canaux-d-authentification-src-main-ipc-auth-js" aria-label="Permalink to &quot;1. Canaux d&#39;Authentification (`src/main/ipc-auth.js`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Canal IPC</th><th>Type</th><th>Paramètres</th><th>Description</th></tr></thead><tbody><tr><td><code>auth:start-device-flow</code></td><td><code>invoke</code></td><td>Aucun</td><td>Déclenche le flux OAuth2 Device Code et retourne le code court ainsi que l&#39;URL de connexion.</td></tr><tr><td><code>auth:poll-device-flow</code></td><td><code>invoke</code></td><td><code>deviceCode</code></td><td>Sonde l&#39;API Microsoft jusqu&#39;à validation par le joueur ou expiration du délai.</td></tr><tr><td><code>auth:save-account</code></td><td><code>invoke</code></td><td><code>accountData</code></td><td>Chiffre et persiste le profil joueur dans le trousseau local.</td></tr><tr><td><code>auth:get-accounts</code></td><td><code>invoke</code></td><td>Aucun</td><td>Retourne la liste des comptes enregistrés (jetons sensibles masqués).</td></tr><tr><td><code>auth:remove-account</code></td><td><code>invoke</code></td><td><code>uuid</code></td><td>Supprime un compte et purge ses identifiants chiffrés du disque.</td></tr><tr><td><code>auth:proxy-skin</code></td><td><code>invoke</code></td><td><code>skinUrl</code></td><td>Agit comme proxy HTTPS pour télécharger la texture du skin sans blocage CORS.</td></tr></tbody></table><hr><h2 id="_2-canaux-de-lancement-et-de-jeu-src-main-ipc-game-js" tabindex="-1">2. Canaux de Lancement et de Jeu (<code>src/main/ipc-game.js</code>) <a class="header-anchor" href="#_2-canaux-de-lancement-et-de-jeu-src-main-ipc-game-js" aria-label="Permalink to &quot;2. Canaux de Lancement et de Jeu (`src/main/ipc-game.js`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Canal IPC</th><th>Type</th><th>Paramètres</th><th>Description</th></tr></thead><tbody><tr><td><code>game:launch-instance</code></td><td><code>invoke</code></td><td><code>instanceConfig</code></td><td>Prépare les fichiers, vérifie les SHA-1 des bibliothèques et lance le processus Java.</td></tr><tr><td><code>game:kill-process</code></td><td><code>invoke</code></td><td><code>instanceId</code></td><td>Envoie un signal <code>SIGTERM</code> (puis <code>SIGKILL</code>) au processus Java en cours d&#39;exécution.</td></tr><tr><td><code>game:detect-java</code></td><td><code>invoke</code></td><td>Aucun</td><td>Analyse les chemins standards du système d&#39;exploitation et retourne la liste des JDK / JRE disponibles.</td></tr><tr><td><code>game:download-java</code></td><td><code>invoke</code></td><td><code>majorVersion</code></td><td>Télécharge et extrait un runtime Java officiel vérifié (Adoptium / Eclipse Temurin).</td></tr><tr><td><code>game:stream-logs</code></td><td><code>send / on</code></td><td>Événement flux</td><td>Transmet les flux standard <code>stdout</code> et <code>stderr</code> de Minecraft vers la console du Renderer.</td></tr></tbody></table><hr><h2 id="_3-canaux-systeme-et-fichiers-src-main-ipc-system-js" tabindex="-1">3. Canaux Système et Fichiers (<code>src/main/ipc-system.js</code>) <a class="header-anchor" href="#_3-canaux-systeme-et-fichiers-src-main-ipc-system-js" aria-label="Permalink to &quot;3. Canaux Système et Fichiers (`src/main/ipc-system.js`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Canal IPC</th><th>Type</th><th>Paramètres</th><th>Description</th></tr></thead><tbody><tr><td><code>system:show-in-folder</code></td><td><code>invoke</code></td><td><code>targetPath</code></td><td>Ouvre l&#39;explorateur de fichiers natif (Explorer, Finder, Nautilus) sur l&#39;élément ciblé.</td></tr><tr><td><code>system:open-dialog-file</code></td><td><code>invoke</code></td><td><code>options</code></td><td>Ouvre une boîte de dialogue native pour sélectionner un fichier (.zip, .jar).</td></tr><tr><td><code>system:open-dialog-folder</code></td><td><code>invoke</code></td><td><code>options</code></td><td>Ouvre une boîte de dialogue native pour sélectionner un dossier de destination.</td></tr><tr><td><code>system:copy-image-to-sandbox</code></td><td><code>invoke</code></td><td><code>srcPath, destName, subDir</code></td><td>Valide l&#39;extension et les <strong>Magic Bytes</strong> de l&#39;image avant de la copier dans la sandbox.</td></tr><tr><td><code>system:discord-set-activity</code></td><td><code>invoke</code></td><td><code>activityPayload</code></td><td>Met à jour le statut Rich Presence sur le client Discord local via Named Pipe.</td></tr><tr><td><code>system:discord-clear</code></td><td><code>invoke</code></td><td>Aucun</td><td>Réinitialise et efface l&#39;activité affichée sur Discord.</td></tr></tbody></table><hr><h2 id="_4-canaux-du-moteur-horizon-src-main-ipc-horizon-js" tabindex="-1">4. Canaux du Moteur Horizon (<code>src/main/ipc-horizon.js</code>) <a class="header-anchor" href="#_4-canaux-du-moteur-horizon-src-main-ipc-horizon-js" aria-label="Permalink to &quot;4. Canaux du Moteur Horizon (`src/main/ipc-horizon.js`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Canal IPC</th><th>Type</th><th>Paramètres</th><th>Description</th></tr></thead><tbody><tr><td><code>horizon:check</code></td><td><code>invoke</code></td><td>Aucun</td><td>Interroge l&#39;état de synchronisation globale et les versions distantes.</td></tr><tr><td><code>horizon:login</code></td><td><code>invoke</code></td><td><code>providerName</code></td><td>Démarre la procédure d&#39;authentification OAuth2 pour Google Drive, Dropbox ou OneDrive.</td></tr><tr><td><code>horizon:sync</code></td><td><code>invoke</code></td><td><code>instanceName</code></td><td>Lance la synchronisation différentielle (téléchargement et application des deltas).</td></tr><tr><td><code>horizon:upload</code></td><td><code>invoke</code></td><td><code>instanceName</code></td><td>Analyse les modifications locales, crée une archive delta et l&#39;envoie sur le cloud.</td></tr><tr><td><code>horizon:quota</code></td><td><code>invoke</code></td><td>Aucun</td><td>Récupère l&#39;espace total, utilisé et disponible sur le stockage cloud connecté.</td></tr><tr><td><code>horizon:rollback</code></td><td><code>invoke</code></td><td><code>instanceName, deltaId</code></td><td>Restaure l&#39;instance à un point de sauvegarde antérieur spécifique.</td></tr><tr><td><code>horizon:purge-lock</code></td><td><code>invoke</code></td><td>Aucun</td><td>Supprime manuellement un fichier <code>horizon.lock</code> orphelin après vérification.</td></tr></tbody></table><hr><h2 id="_5-canaux-de-mise-a-jour-automatique-src-main-updater-js" tabindex="-1">5. Canaux de Mise à Jour Automatique (<code>src/main/updater.js</code>) <a class="header-anchor" href="#_5-canaux-de-mise-a-jour-automatique-src-main-updater-js" aria-label="Permalink to &quot;5. Canaux de Mise à Jour Automatique (`src/main/updater.js`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Canal IPC</th><th>Type</th><th>Paramètres</th><th>Description</th></tr></thead><tbody><tr><td><code>updater:check-for-updates</code></td><td><code>invoke</code></td><td>Aucun</td><td>Vérifie sur GitHub Releases si une nouvelle version du lanceur est disponible.</td></tr><tr><td><code>updater:download-update</code></td><td><code>invoke</code></td><td>Aucun</td><td>Télécharge la mise à jour en arrière-plan avec rapport de progression.</td></tr><tr><td><code>updater:quit-and-install</code></td><td><code>invoke</code></td><td>Aucun</td><td>Redémarre l&#39;application et applique la nouvelle version.</td></tr></tbody></table>',18)])])}const m=t(c,[["render",r]]);export{p as __pageData,m as default};
